from pwn import remote
p = remote('pwn.chal.csaw.io', 31140, timeout=5)
# receive all data (should include prompt and flag)
data = b''
while True:
    try:
        chunk = p.recv(4096)
        if not chunk:
            break
        data += chunk
    except Exception as e:
        break
print('Data:', data)

